\begin{tikzpicture}[font=\sffamily, scale=0.85]
    % Axes
    \draw[-Stealth] (0,0) -- (12,0) node[right, align=left] {partial pressure of\\oxygen / kPa};
    \draw[-Stealth] (0,0) -- (0,8) node[above] {saturation of haemoglobin / \%};

    % Horizontal ticks and grid (0 to 14, every 2 -> 14/7 = 2 cm per unit? Let's use 0.75cm per unit so 14 is at 10.5)
    % Let's map: 2 kPa = 1.5 cm -> 14 kPa = 10.5 cm
    % Let's map y: 20% = 1.2 cm -> 100% = 6 cm

    \pgfmathsetmacro{\xscale}{0.75}
    \pgfmathsetmacro{\yscale}{0.06} % 100% = 6 cm, so 1% = 0.06 cm

    % Grid lines (light grey, optional or just ticks)
    \foreach \x in {2, 4, 6, 8, 10, 12, 14} {
        \draw[gray!30] (\x*\xscale, 0) -- (\x*\xscale, 100*\yscale);
        \draw (\x*\xscale, 2pt) -- (\x*\xscale, -2pt) node[below, font=\small] {\x};
    }
    \node[below left, font=\small] at (0,0) {0};

    \foreach \y in {20, 40, 60, 80, 100} {
        \draw[gray!30] (0, \y*\yscale) -- (14*\xscale, \y*\yscale);
        \draw (2pt, \y*\yscale) -- (-2pt, \y*\yscale) node[left, font=\small] {\y};
    }

    % Curves
    % Curve A (solid): reaches 50% at ~3.5 kPa, upper asymptote near 98%
    % Using logistic-like or smooth bezier curves
    \draw[thick] (0, 2*\yscale) 
        .. controls (2*\xscale, 10*\yscale) and (3*\xscale, 35*\yscale) .. (3.5*\xscale, 50*\yscale)
        .. controls (4.5*\xscale, 75*\yscale) and (7*\xscale, 95*\yscale) .. (14*\xscale, 98*\yscale);

    % Curve B (dashed): shifted right, reaches 50% at ~4.8 kPa
    \draw[thick, dashed] (0, 1.5*\yscale) 
        .. controls (2.5*\xscale, 8*\yscale) and (4*\xscale, 30*\yscale) .. (4.8*\xscale, 50*\yscale)
        .. controls (6*\xscale, 72*\yscale) and (8.5*\xscale, 94*\yscale) .. (14*\xscale, 97*\yscale);

    % Labels for curves
    \node[above right] at (9*\xscale, 85*\yscale) {A};
    \node[above right] at (9.5*\xscale, 70*\yscale) {B};

    % Caption
    \node[above, font=\bfseries] at (7*\xscale, -1.5) {Fig. 7.1};

\end{tikzpicture}
